fn contextual_callback_unannotated_member_array_stays_unknown() {
    let mut ws = VirtualWorkspace::new();
    let file = ws.def(
        r#"
        local Constants = {}
        Constants.handlers = { function(value)
            local observed_value = value
        end }
    "#,
    );
    expect_that!(
        local_type(&ws, file, "observed_value"),
        eq(&LuaType::Unknown)
    );
}

